137	    private static int[] computeShortestPaths(Graph graph, int src) {
138	        int[] distances = new int[graph.vertexCount()];
139	        Arrays.fill(distances, UNREACHABLE);
140	        distances[src] = 0;
141	
142	        PriorityQueue<QueueEntry> minHeap =
143	                new PriorityQueue<>(Comparator.comparingInt(entry -> entry.distance));
144	        minHeap.offer(new QueueEntry(0, src));
145	
146	        while (!minHeap.isEmpty()) {
147	            QueueEntry current = minHeap.poll();
148	            if (current.distance != distances[current.vertex]) {
149	                continue;
150	            }
151	
152	            for (Edge edge : graph.neighborsOf(current.vertex)) {
153	                int nextDistance = addDistances(current.distance, edge.weight);
154	                if (nextDistance < distances[edge.to]) {
155	                    distances[edge.to] = nextDistance;
156	                    minHeap.offer(new QueueEntry(distances[edge.to], edge.to));
157	                }
158	            }
159	        }
160	
161	        return distances;
162	    }
