126	        private ShortestPathSolver(Graph graph, int source) {
127	            this.graph = graph;
128	            this.distances = createDistances(graph.vertexCount(), source);
129	            this.minHeap = new PriorityQueue<>(Comparator.comparingInt(entry -> entry.distance));
130	            minHeap.offer(new QueueEntry(0, source));
131	        }
