137	        private int[] run() {
138	            while (!minHeap.isEmpty()) {
139	                QueueEntry current = minHeap.poll();
140	                if (isStale(current)) {
141	                    continue;
142	                }
143	
144	                relaxNeighborsOf(current);
145	            }
146	            return distances;
147	        }
